using FluentValidation;
namespace FintechApp.Requests.TransactionStatusChange { public class CreateTransactionStatusChangeRequest { public int UserID { get; set; } public int TransactionMasterID { get; set; } public int TransactionDOCInt { get; set; } public string OldStatus { get; set; } = string.Empty; public string NewStatus { get; set; } = string.Empty; public decimal Amount { get; set; } public string Remark { get; set; } = string.Empty; } public class CreateTransactionStatusChangeRequestValidator : AbstractValidator<CreateTransactionStatusChangeRequest> { public CreateTransactionStatusChangeRequestValidator() { RuleFor(x => x.UserID).GreaterThan(0); } } }
